CREATE TABLE IF NOT EXISTS identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),device_id TEXT NOT NULL,public_key TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,owner TEXT NOT NULL DEFAULT '',claim_hash TEXT NOT NULL DEFAULT '',claim_expires INTEGER NOT NULL DEFAULT 0,pending_owner TEXT NOT NULL DEFAULT '',confirm_code TEXT NOT NULL DEFAULT '');

CREATE TABLE IF NOT EXISTS challenges(nonce TEXT PRIMARY KEY,expires INTEGER NOT NULL);
